  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// BETTER — minimal response; add IP allowlisting if internal-only
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// BEST for internal-only health checks — restrict to private IP ranges
const internalOnly = (req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const isPrivate = /^(127\.|10\.|172\.(1[6-9]|2\d|3[01])\.|192\.168\.)/.test(ip);
  if (!isPrivate) return res.status(403).json({ error: 'Forbidden.' });
