// In production, redirect HTTP → HTTPS at the load balancer/reverse proxy.
// Additionally, set HSTS via helmet:
app.use(helmet.hsts({
  maxAge: 31536000,       // 1 year in seconds
  includeSubDomains: true,
  preload: true,
}));

// Optionally enforce in-app for environments without a proxy:
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(301, `https://${req.headers.host}${req.url}`);
