// Content-Security-Policy, removes X-Powered-By, and more.
```

---

#### 2. No Rate Limiting (OWASP A04 – Insecure Design / DoS risk)

Any endpoint — including future auth endpoints — is completely unthrottled. This enables brute-force attacks and denial-of-service.

**Fix:**
```js
const rateLimit = require('express-rate-limit'); // npm install express-rate-limit

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});

app.use(limiter); // Apply globally, or per-route as needed
```

---

#### 3. No Authentication or Authorization on `/users` (OWASP A01 – Broken Access Control)

`/users` returns a list of user data (including emails) with zero access control. Any anonymous caller can enumerate users.

**Fix — add a JWT auth middleware:**
```js
const jwt = require('jsonwebtoken'); // npm install jsonwebtoken

function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed token' });
  }
  try {
    req.user = jwt.verify(authHeader.slice(7), process.env.JWT_SECRET);
    next();
  } catch {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// Apply to protected routes:
