```

```js
const { expressjwt: expressJwt } = require('express-jwt');

const authenticate = expressJwt({
  secret: process.env.JWT_SECRET, // Never hardcode — see Finding 7
  algorithms: ['HS256'],
});

// Protect routes that return sensitive data
