```

```js
// config/secrets.js
'use strict';

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION ?? 'us-east-1' });

async function loadSecrets() {
  const command = new GetSecretValueCommand({ SecretId: process.env.SECRET_NAME });
  const response = await client.send(command);

  const secrets = JSON.parse(response.SecretString);

  // Validate that expected keys exist in the fetched secret
  const REQUIRED_KEYS = ['JWT_SECRET', 'DB_PASSWORD'];
  const missing = REQUIRED_KEYS.filter((k) => !secrets[k]);
  if (missing.length) {
    throw new Error(`Secrets bundle missing required keys: ${missing.join(', ')}`);
  }

  return secrets;
}

module.exports = { loadSecrets };
```

```js
