const { loadSecrets } = require('./config/secrets');

async function bootstrap() {
  const secrets = await loadSecrets(); // Fetch before binding port
  const app = express();

  // Pass secrets explicitly — never write them back to process.env
  const authenticate = buildAuthMiddleware(secrets.JWT_SECRET);

  app.use(authenticate);
  // ... rest of setup ...

  app.listen(process.env.PORT ?? 3000);
}

bootstrap().catch((err) => {
  console.error('Failed to start server:', err.message);
  process.exit(1);
});
```

