    const users = await UserService.findAll();
    const sanitized = users.map(u =>
      Object.fromEntries(ALLOWED_FIELDS.map(f => [f, u[f]]))
    );
    res.json(sanitized);
  } catch (err) {
    next(err); // centralised error handler — see below
  }
});
```

