### 2. No Authentication or Authorization on Any Route (OWASP A01 – Broken Access Control)

**Problem:** Every route is fully public. There is no authentication middleware, no session handling, no JWT validation, and no role-based access control anywhere in the file.

```js
// ❌ Current: anyone on the internet can call /users
app.get('/users', (req, res) => { ... });
```

**Fix:** Add an authentication middleware and attach it globally or per-route:

```js
// ✅ auth.middleware.js
const jwt = require('jsonwebtoken');

function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed token' });
  }
  try {
    req.user = jwt.verify(
      authHeader.slice(7),
      process.env.JWT_SECRET   // loaded from env, never hardcoded
    );
    next();
  } catch {
    res.status(401).json({ error: 'Invalid or expired token' });
  }
}

function requireRole(...roles) {
  return (req, res, next) => {
    if (!roles.includes(req.user?.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
}

module.exports = { requireAuth, requireRole };
```

