## 🟠 High Severity Issues

### 3. No Input Parsing or Validation Middleware (OWASP A03 – Injection)

**Problem:** `express.json()` and `express.urlencoded()` are absent. If POST/PUT routes are added later (very likely), unsanitized request bodies will be processed directly, opening the door to injection attacks.

**Fix:** Add body parsers with strict size limits and a validation library before any routes:

```js
// ✅ Add near the top of app.js, before routes
const express = require('express');
const { body, param, query, validationResult } = require('express-validator');

const app = express();

app.use(express.json({ limit: '10kb' }));        // reject oversized payloads
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// Reusable validation error handler
function validate(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
}

// Example of a validated route
app.post('/users',
  requireAuth,
  requireRole('admin'),
  body('name').isString().trim().isLength({ min: 1, max: 100 }).escape(),
  body('email').isEmail().normalizeEmail(),
  validate,
  async (req, res, next) => {
    // req.body is now validated and sanitized
  }
);
```

