  const statusCode = err.status ?? 500;

  // Log full error internally
  console.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Return a sanitized response — never expose err.message or err.stack
  res.status(statusCode).json({
    error: statusCode < 500 ? err.message : 'Internal server error',
  });
});
```

