**Fix:** Add a centralized error handler as the **last** middleware:

```js
// ✅ Last middleware registered — catches all errors passed via next(err)
app.use((err, req, res, next) => {
  const isProd = process.env.NODE_ENV === 'production';

  // ✅ Always log the full error server-side
  console.error({
    message: err.message,
    stack:   err.stack,
    path:    req.path,
    method:  req.method,
  });

  res.status(err.status || 500).json({
    error: isProd ? 'An unexpected error occurred.' : err.message, // ✅ No stack traces to client in prod
