// npm install @aws-sdk/client-secrets-manager
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function loadSecrets() {
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
  const response = await client.send(
    new GetSecretValueCommand({ SecretId: 'prod/myapp/secrets' })
  );
  const secrets = JSON.parse(response.SecretString);

  // Inject into process.env at startup — never log these
  process.env.DATABASE_URL   = secrets.DATABASE_URL;
  process.env.JWT_SECRET     = secrets.JWT_SECRET;
  process.env.STRIPE_SECRET  = secrets.STRIPE_SECRET_KEY;
}

// Call before app.listen()
loadSecrets().then(() => {
  app.listen(process.env.PORT || 3000);
}).catch(err => {
  console.error('Failed to load secrets — aborting startup');
  process.exit(1); // Fail fast; never start without secrets
});
```

### 🟠 Finding 4 — No secret rotation or validation at startup

Even with a secrets manager, secrets should be validated at startup so the app fails loudly rather than starting in a broken state.

```js
function assertRequiredEnv() {
  const required = [
    'DATABASE_URL',
    'JWT_SECRET',
    'STRIPE_SECRET_KEY',
  ];
  const missing = required.filter(k => !process.env[k]);
  if (missing.length > 0) {
    console.error(`Missing required environment variables: ${missing.join(', ')}`);
    process.exit(1);
  }
}

assertRequiredEnv(); // call before anything else
```

---

