// Global error handler — MUST have 4 args
app.use((err, req, res, next) => {
  // Log full detail internally (use a real logger like winston/pino)
  console.error({
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
  });

  // Return NOTHING useful to the client
  const status = err.status || err.statusCode || 500;
  const isProd = process.env.NODE_ENV === 'production';
  res.status(status).json({
