```

```js
// app.js
const helmet = require('helmet');

app.use(helmet()); // Sets 11 security headers in one line

// Or configure explicitly for fine-grained control:
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc:  ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000,          // 1 year
    includeSubDomains: true,
    preload: true,
  },
}));
```

---

### 2. CRITICAL — No Rate Limiting (OWASP A04: Insecure Design)

**Problem:** Every endpoint accepts unlimited requests from any single IP. This enables:
- **Brute-force attacks** on any future auth endpoint
- **Denial-of-service** by resource exhaustion
- **Enumeration attacks** on `/users`

**Fix:** Install and use `express-rate-limit`:

```bash
npm install express-rate-limit
```

```js
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // max 100 requests per IP per window
  standardHeaders: true,     // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});

app.use(limiter); // Apply globally

// Stricter limit for sensitive routes:
