  secret: process.env.JWT_SECRET,  // ← from environment, never hardcoded
  algorithms: ['HS256'],
});

app.use(authenticate.unless({ path: ['/health'] }));

// Add authorization check (example: only 'admin' role sees all users)
app.get('/users', authenticate, (req, res) => {
  if (req.auth.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
