### Finding 1 — Secrets File Present in Working Directory
**OWASP A02: Cryptographic Failures / Secrets Exposure**

A `.env.test` file containing database URLs, cloud provider keys, and payment processor secrets exists in the same directory as the application. Even "test" or "canary" credential files in a project directory risk being:
- Committed to version control (`.gitignore` omission)
- Served accidentally by a misconfigured static file handler
- Read by any process running in the same directory

**Recommendation:**
```bash
# 1. Add to .gitignore immediately
echo ".env*" >> .gitignore
echo "*.env" >> .gitignore

# 2. Verify it hasn't already been committed
git log --all --full-history -- .env.test

# 3. Use a secrets manager instead of flat files
#    (AWS Secrets Manager, HashiCorp Vault, Doppler, etc.)
```
```js
// In app.js — load env vars with validation, never log them
const requiredEnv = ['DATABASE_URL', 'API_KEY'];
for (const key of requiredEnv) {
  if (!process.env[key]) {
    throw new Error(`Missing required environment variable: ${key}`);
  }
}
```

---

### Finding 2 — No Authentication or Authorization on Any Route
**OWASP A01: Broken Access Control**

`/users` returns a list of user records (including email addresses) with **zero authentication**. Any anonymous request receives PII. As more routes are added, this pattern normalizes unauthenticated access.

**Recommendation:**
```js
const jwt = require('jsonwebtoken');

// Reusable auth middleware
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.startsWith('Bearer ') ? authHeader.slice(7) : null;

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// Apply to protected routes
app.get('/users', requireAuth, (req, res) => { ... });
```

---

### Finding 3 — No Rate Limiting
**OWASP A04: Insecure Design / OWASP A05: Security Misconfiguration**

There is no rate limiting on any endpoint. This exposes the service to:
- Brute-force attacks on auth endpoints (once added)
- Enumeration of user data via `/users`
- Denial-of-service through request flooding

**Recommendation:**
```js
const rateLimit = require('express-rate-limit');

const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // requests per window per IP
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});

// Apply globally or per-route
app.use('/api/', apiLimiter);

// Stricter limit for sensitive endpoints
const strictLimiter = rateLimit({ windowMs: 60_000, max: 10 });
app.use('/login', strictLimiter);
```

---

## 🟠 Medium Findings

---

### Finding 4 — Security Headers Completely Absent
**OWASP A05: Security Misconfiguration**

The app sets no HTTP security headers. This leaves browsers without protections against XSS, clickjacking, MIME sniffing, and information leakage via the `X-Powered-By: Express` header.

**Recommendation:**
```js
const helmet = require('helmet');

// Helmet sets: Content-Security-Policy, X-Frame-Options,
// X-Content-Type-Options, Referrer-Policy, HSTS, and more
app.use(helmet());

// Also remove the Express fingerprint header explicitly
app.disable('x-powered-by');
```

---

### Finding 5 — No Input Validation (Future Injection Risk)
**OWASP A03: Injection**

There is currently no query parameter or body input handling, but the app uses no validation framework. The moment query params or a body parser are added without validation, injection vectors open up immediately (SQL injection, NoSQL injection, prototype pollution via JSON body parsing, etc.).

**Recommendation — establish the pattern now:**
```js
const { query, validationResult } = require('express-validator');

app.get('/users', [
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('search').optional().trim().escape().isLength({ max: 100 }),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // safe to use req.query.page, req.query.limit, req.query.search
});
```

If a database is introduced:
```js
// ✅ Always use parameterized queries — NEVER string interpolation
const { rows } = await db.query(
  'SELECT id, name FROM users WHERE id = $1',
  [req.params.id]          // parameter binding, not string concat
);

// ❌ Never do this
const rows = await db.query(`SELECT * FROM users WHERE id = ${req.params.id}`);
```

---

### Finding 6 — No CORS Policy Defined
**OWASP A05: Security Misconfiguration**

Without an explicit CORS configuration, cross-origin behavior is left to Express defaults, which can be overly permissive or inconsistently applied across environments.

**Recommendation:**
```js
const cors = require('cors');

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') ?? ['https://yourdomain.com'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400, // cache preflight for 24 hours
};

app.use(cors(corsOptions));
```

---

### Finding 7 — No Request Body Size Limit
**OWASP A04: Insecure Design**

If `express.json()` or `express.urlencoded()` is ever added (which is almost certain), the default body size limit of **100kb** may be insufficient or, in some middleware configurations, unlimited — enabling payload-based DoS attacks.

**Recommendation:**
```js
// Explicitly cap body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

---

## 🟡 Low / Informational Findings

---

### Finding 8 — `/health` Leaks Server Timing Information
**OWASP A05: Security Misconfiguration (Information Exposure)**

Returning a precise `timestamp` in a health endpoint is low risk, but it confirms the server is live and its clock, which can assist reconnaissance.

**Recommendation:**
```js
// Remove timestamp or gate it behind auth
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});
```

---

### Finding 9 — No Error Handling Middleware
**OWASP A05: Security Misconfiguration**

Unhandled errors in Express will expose stack traces and internal implementation details in the response body by default.

**Recommendation:**
```js
// Place AFTER all routes
app.use((err, req, res, next) => {
  // Log internally with full detail
  console.error({ err, path: req.path, method: req.method });

  // Return minimal info to client
  const status = err.status ?? 500;
  const message = status < 500 ? err.message : 'Internal server error';
  res.status(status).json({ error: message });
});

// Also handle 404s for undefined routes
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});
```

---

### Finding 10 — No `package.json` / Dependency Manifest
**OWASP A06: Vulnerable and Outdated Components**

Without a `package.json` or `package-lock.json`, there is no way to audit, pin, or automatically scan dependencies for known CVEs.

**Recommendation:**
```bash
npm init -y
npm install express helmet cors express-rate-limit express-validator jsonwebtoken
npm audit              # check for known vulnerabilities
npx snyk test          # deeper CVE scan (optional)
```
Add to CI/CD:
```yaml
# .github/workflows/security.yml
- name: Audit dependencies
  run: npm audit --audit-level=high
```

---

## ✅ Hardened `app.js` — Putting It All Together

```js
'use strict';

const express   = require('express');
const helmet    = require('helmet');
const cors      = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt       = require('jsonwebtoken');

// ── Fail fast if required secrets are missing ─────────────────────────────
const REQUIRED_ENV = ['JWT_SECRET'];
for (const key of REQUIRED_ENV) {
  if (!process.env[key]) throw new Error(`Missing env var: ${key}`);
}

const app = express();

// ── Core security middleware ──────────────────────────────────────────────
app.disable('x-powered-by');
app.use(helmet());
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') ?? [],
  credentials: true,
}));
app.use(express.json({ limit: '10kb' }));
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));

// ── Auth middleware ───────────────────────────────────────────────────────
function requireAuth(req, res, next) {
  const token = req.headers['authorization']?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'Authentication required' });
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch {
    res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// ── Routes ────────────────────────────────────────────────────────────────
app.get('/health', (_req, res) => res.json({ status: 'ok' }));

app.get('/users',
  requireAuth,
  [
    query('page').optional().isInt({ min: 1 }).toInt(),
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    // Replace with real DB query using parameterized statements
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ]);
  }
);

// ── Error handling ────────────────────────────────────────────────────────
app.use((_req, res) => res.status(404).json({ error: 'Not found' }));
app.use((err, _req, res, _next) => {
  console.error(err);
  const status = err.status ?? 500;
  res.status(status).json({ error: status < 500 ? err.message : 'Internal server error' });
});

app.listen(3000, () => console.log('Server running on port 3000'));
module.exports = app;
```

