```js
const jwt = require('jsonwebtoken');

function authenticate(req, res, next) {
  const authHeader = req.request.headers['authorization'];
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or invalid Authorization header' });
  }
  try {
    const token = authHeader.split(' ')[1];
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// Apply to protected routes
app.get('/users', authenticate, (req, res) => { ... });
```

---

### 2. Secrets Must Not Be Hardcoded
There are no secrets *yet*, but the pattern of adding them inline is a common next step. The `JWT_SECRET` above and any DB credentials must come from environment variables — never source code.

**Recommendation:** Use `dotenv` with a `.env` file excluded from version control.

```js
// At the very top of app.js
require('dotenv').config();

// .env (never commit this)
JWT_SECRET=a_long_random_secret_min_32_chars
DB_URL=postgres://user:pass@host/db

// .gitignore
.env
```

---

## 🟠 High Severity Issues

### 3. No Security HTTP Headers (Missing Helmet)
Express ships with no protective HTTP headers. This leaves the app open to clickjacking, MIME sniffing, XSS via reflected content, and more (OWASP A05: Security Misconfiguration).

**Recommendation:** Add `helmet` as the first middleware.

```js
const helmet = require('helmet');

// Must be registered BEFORE all routes
app.use(helmet());
// Sets: Content-Security-Policy, X-Frame-Options, X-Content-Type-Options,
//       Strict-Transport-Security, Referrer-Policy, etc.
```

---

### 4. No Rate Limiting (OWASP A07: Identification & Authentication Failures)
All endpoints are unthrottled. This enables brute-force attacks on login endpoints, credential stuffing, and DoS via resource exhaustion.

**Recommendation:**

```js
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});

app.use(limiter); // Apply globally

// Stricter limit for sensitive endpoints
const authLimiter = rateLimit({ windowMs: 15 * 60 * 1000, max: 10 });
app.use('/login', authLimiter);
```

---

### 5. No Request Body Parsing or Input Validation
`express.json()` is not registered, meaning POST/PUT body data is silently ignored. When it *is* added, there is no validation — a direct path to injection and unexpected behavior (OWASP A03: Injection).

**Recommendation:** Parse bodies with size limits and validate all input.

```js
const { body, param, query, validationResult } = require('express-validator');

// Limit body size to prevent payload-based DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Example: validated POST /users route
app.post('/users',
  authenticate,
  body('name').isString().trim().isLength({ min: 1, max: 100 }).escape(),
  body('email').isEmail().normalizeEmail(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to use req.body here
  }
);
```

---

### 6. No CORS Policy
Express does not restrict cross-origin requests by default. Any website can make requests to this API on behalf of a logged-in user (OWASP A01: Broken Access Control).

**Recommendation:**

```js
const cors = require('cors');

app.use(cors({
  origin: ['https://yourdomain.com'], // explicit allowlist, never use '*' with credentials
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
}));
```

---

## 🟡 Medium Severity Issues

### 7. Sensitive Data Exposure on `/users` (OWASP A02)
User data (even mock data) is returned wholesale. Real implementations routinely leak password hashes, tokens, or internal IDs this way.

**Recommendation:** Always use an explicit allowlist of fields to return — never pass database objects directly to `res.json()`.

```js
function sanitizeUser(user) {
  const { id, name, email } = user; // only expose what's needed
  return { id, name, email };
}

app.get('/users', authenticate, (req, res) => {
  const users = getAllUsers(); // from DB
  res.json(users.map(sanitizeUser));
});
```

---

### 8. No Centralized Error Handler
Unhandled exceptions will bubble up through Express's default error handler, which may leak stack traces, file paths, or dependency versions to the client in non-production environments.

**Recommendation:** Add a centralized error handler as the *last* middleware.

```js
// Catch async errors (Express 4)
const asyncHandler = fn => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);

// Centralized error handler — must have 4 parameters
app.use((err, req, res, next) => {
  const status = err.status || 500;
  // Log internally (never send stack traces to the client)
  console.error(err); // replace with a proper logger (e.g., winston/pino)
  res.status(status).json({
    error: process.env.NODE_ENV === 'production' ? 'Internal server error' : err.message,
  });
});
```

---

### 9. `/health` Endpoint May Leak System Information
Health endpoints often evolve to include uptime, memory usage, dependency versions, or environment names — all useful to attackers for fingerprinting.

**Recommendation:** Keep health endpoints minimal in production, and gate detailed diagnostics behind authentication.

```js
app.get('/health', (req, res) => {
  // Public: minimal response only
  res.json({ status: 'ok' });
});

app.get('/health/details', authenticate, (req, res) => {
  // Gated: detailed diagnostics for ops tooling
  res.json({ status: 'ok', uptime: process.uptime(), timestamp: new Date().toISOString() });
});
```

---

### 10. Server Listens on All Interfaces
`app.listen(3000)` binds to `0.0.0.0` by default, exposing the port on every network interface including public-facing ones.

**Recommendation:** Bind explicitly to localhost and put a reverse proxy (nginx/Caddy) in front.

```js
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '127.0.0.1'; // localhost only

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
});
```

