{ id: 1, name: 'Alice', email: 'alice@example.com' }
```

**Recommendation:** Always fetch from a data store, and never commit real user data:

```js
const db = require('./db'); // your database abstraction

app.get('/users', requireAuth, async (req, res, next) => {
