### Step 2: Use a secrets manager appropriate to your environment

**Option A — AWS Secrets Manager (production recommended)**
```js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function getSecret(secretName) {
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
  const response = await client.send(new GetSecretValueCommand({ SecretId: secretName }));
  return JSON.parse(response.SecretString);
}

// Load before the app starts — fail fast if secrets are unavailable
async function bootstrap() {
  const secrets = await getSecret('myapp/production');
  process.env.JWT_SECRET  = secrets.jwtSecret;   // Inject into env at runtime only
  process.env.DB_PASSWORD = secrets.dbPassword;

  require('./server'); // Start the app only after secrets are loaded
}

bootstrap().catch(err => {
  console.error('Failed to load secrets — shutting down:', err.message);
  process.exit(1);
});
```

**Option B — HashiCorp Vault**
```js
const vault = require('node-vault')({ endpoint: process.env.VAULT_ADDR });

async function getSecret(path) {
  await vault.approleLogin({
    role_id:   process.env.VAULT_ROLE_ID,
    secret_id: process.env.VAULT_SECRET_ID
  });
  const result = await vault.read(path);
  return result.data;
}
```

**Option C — `.env` files for local development only**
```js
// Only load .env in non-production environments
if (process.env.NODE_ENV !== 'production') {
  require('dotenv').config();
}
```
```bash
# .env — local development only
JWT_SECRET=local-dev-secret-not-real
DB_PASSWORD=localdevpassword
```
```gitignore
